import{_ as t,o as e,c as i,a5 as s}from"./chunks/framework.a5no_H3L.js";const p=JSON.parse('{"title":"消息队列选型","description":"选消息队列不是选「最好的」，而是选「最适合的」。本章聚焦 RabbitMQ 的核心优势与适用场景。完整技术对比见 Kafka · 消息队列选型。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/01-basics/chapter-05-mq-comparison.md","filePath":"rabbitmq/01-basics/chapter-05-mq-comparison.md"}'),r={name:"rabbitmq/01-basics/chapter-05-mq-comparison.md"};function l(c,a,d,b,m,n){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="消息队列选型" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">消息队列选型 <a class="header-anchor" href="#消息队列选型" aria-label="Permalink to &quot;消息队列选型&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><p data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">选消息队列不是选「最好的」，而是选「最适合的」。本章聚焦 RabbitMQ 的核心优势与适用场景。完整技术对比见 <a href="/kafka/01-intro/chapter-03-mq-comparison.html">Kafka · 消息队列选型</a>。</p></blockquote><h2 id="rabbitmq-的核心优势" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">RabbitMQ 的核心优势 <a class="header-anchor" href="#rabbitmq-的核心优势" aria-label="Permalink to &quot;RabbitMQ 的核心优势&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="7" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><th style="text-align:left;">维度</th><th style="text-align:left;">RabbitMQ 的特点</th></tr></thead><tbody data-src-line="9" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="9" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">路由能力</td><td style="text-align:left;">4 种 Exchange（Direct/Topic/Fanout/Headers），路由规则灵活</td></tr><tr data-src-line="10" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">延迟</td><td style="text-align:left;">消息路由与投递模型适合对交互延迟敏感的业务，实际端到端延迟取决于队列类型、确认策略、持久化与负载</td></tr><tr data-src-line="11" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">协议支持</td><td style="text-align:left;">支持 AMQP，可通过插件支持 MQTT、STOMP，适合有 MQTT 接入需求的 IoT 场景</td></tr><tr data-src-line="12" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">死信队列</td><td style="text-align:left;">提供原生死信机制，需配置 DLX 及触发条件</td></tr><tr data-src-line="13" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">延迟消息</td><td style="text-align:left;">可经 TTL+DLX 延迟转发；RabbitMQ 4.4 起 Quorum Queue 原生支持延迟投递，旧版延迟交换机插件已停止维护</td></tr><tr data-src-line="14" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">运维成本</td><td style="text-align:left;">小规模业务场景下部署较轻，实际成本取决于集群规模、高可用要求与运维方式</td></tr></tbody></table><h2 id="选-rabbitmq-的场景" tabindex="-1" data-src-line="16" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">选 RabbitMQ 的场景 <a class="header-anchor" href="#选-rabbitmq-的场景" aria-label="Permalink to &quot;选 RabbitMQ 的场景&quot;">​</a></h2><ul data-src-line="18" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><li data-src-line="18" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">复杂路由规则（按 routing key 精确/模糊匹配）</li><li data-src-line="19" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">消息量中等，吞吐需求可由单节点或小集群满足</li><li data-src-line="20" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">对交互延迟敏感的业务</li><li data-src-line="21" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">IoT 设备通信（MQTT 协议）</li><li data-src-line="22" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">企业内部微服务间可靠投递</li><li data-src-line="23" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">需要死信队列、延迟消息等高级特性</li></ul><h2 id="通常优先考虑其他方案的场景" tabindex="-1" data-src-line="25" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">通常优先考虑其他方案的场景 <a class="header-anchor" href="#通常优先考虑其他方案的场景" aria-label="Permalink to &quot;通常优先考虑其他方案的场景&quot;">​</a></h2><table tabindex="0"><thead data-src-line="27" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="27" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><th style="text-align:left;">场景</th><th style="text-align:left;">原因</th><th style="text-align:left;">推荐</th></tr></thead><tbody data-src-line="29" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><tr data-src-line="29" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">日志收集/大数据流</td><td style="text-align:left;">长期保留、大规模事件流及多消费者独立回放通常更适合成熟日志流平台；RabbitMQ Streams 也具备日志式保留与 offset 消费能力</td><td style="text-align:left;">Kafka</td></tr><tr data-src-line="30" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">极高吞吐</td><td style="text-align:left;">需评估集群与队列类型实际上限后再决定</td><td style="text-align:left;">Kafka / Pulsar</td></tr><tr data-src-line="31" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">消息回溯</td><td style="text-align:left;">经典队列无基于 offset 的原生历史重读，重新入队/重发布语义与成本不同；RabbitMQ Streams 支持日志式保留与 offset 消费</td><td style="text-align:left;">Kafka</td></tr><tr data-src-line="32" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><td style="text-align:left;">流处理</td><td style="text-align:left;">无原生流处理引擎</td><td style="text-align:left;">Kafka Streams / Flink</td></tr></tbody></table><h2 id="组合使用" tabindex="-1" data-src-line="34" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">组合使用 <a class="header-anchor" href="#组合使用" aria-label="Permalink to &quot;组合使用&quot;">​</a></h2><p data-src-line="36" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">实际项目中经常组合：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IoT 设备 ──MQTT──▶ RabbitMQ ──AMQP──▶ 业务服务</span></span>
<span class="line"><span>                                      │</span></span>
<span class="line"><span>                                      ▼</span></span>
<span class="line"><span>                              Kafka（日志/事件流）</span></span></code></pre></div><p data-src-line="45" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">上图表达的是业务服务处理 RabbitMQ 消息后，将日志/事件写入 Kafka 的转发链路。若 RabbitMQ 与 Kafka 承载的是互不相关的独立消息流，应去掉该箭头。生产环境需处理 Kafka 写入失败、重复投递与重试；要求可靠转发时应设计幂等机制与补偿方案。</p><blockquote data-src-line="47" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md"><p data-src-line="47" data-src-file="rabbitmq/01-basics/chapter-05-mq-comparison.md">不要为了「统一技术栈」强行用一个 MQ 解决所有问题。RabbitMQ 擅长业务消息、灵活路由；Kafka 擅长大数据量、高吞吐。各取所长。</p></blockquote>`,13)])])}const f=t(r,[["render",l]]);export{p as __pageData,f as default};
